fn parallel_sum(xs: &[i64]) -> i64 {
    std::thread::scope(|scope| {
        let (a,b)=xs.split_at(xs.len()/2);
        let left=scope.spawn(|| a.iter().sum::<i64>());
        let right=scope.spawn(|| b.iter().sum::<i64>());
        left.join().unwrap()+right.join().unwrap()
    })
}
fn main() {}

